def compute(vars):
    original_amount = vars["v1"]
    remaining_balance = vars["v2"]
    received = original_amount - remaining_balance

    return {
        "value": received,
        "trace": {
            "original_amount": original_amount,
            "remaining_balance": remaining_balance,
            "received": received,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
